-- Enforce branch scope on Phase 2 records.
drop policy if exists invoices_select on public.invoices; drop policy if exists invoices_insert on public.invoices; create policy invoices_branch_select on public.invoices for select to authenticated using(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id)); create policy invoices_branch_insert on public.invoices for insert to authenticated with check(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id) and public.has_permission('payments.manage'));
drop policy if exists invoice_items_select on public.invoice_items; drop policy if exists invoice_items_insert on public.invoice_items; create policy invoice_items_branch_select on public.invoice_items for select to authenticated using(exists(select 1 from public.invoices i where i.id=invoice_id and i.company_id=public.get_my_company_id() and public.user_has_branch_access(i.branch_id))); create policy invoice_items_branch_insert on public.invoice_items for insert to authenticated with check(exists(select 1 from public.invoices i where i.id=invoice_id and i.company_id=public.get_my_company_id() and public.user_has_branch_access(i.branch_id) and public.has_permission('payments.manage')));
drop policy if exists customer_debt_select on public.customer_debt_ledger; drop policy if exists customer_debt_insert on public.customer_debt_ledger; create policy customer_debt_branch_select on public.customer_debt_ledger for select to authenticated using(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id)); create policy customer_debt_branch_insert on public.customer_debt_ledger for insert to authenticated with check(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id) and public.has_permission('payments.manage'));
drop policy if exists repair_assignments_select on public.repair_assignments; drop policy if exists repair_assignments_insert on public.repair_assignments; create policy repair_assignments_branch_select on public.repair_assignments for select to authenticated using(company_id=public.get_my_company_id() and exists(select 1 from public.repairs r where r.id=repair_id and public.user_has_branch_access(r.branch_id))); create policy repair_assignments_branch_insert on public.repair_assignments for insert to authenticated with check(company_id=public.get_my_company_id() and exists(select 1 from public.repairs r where r.id=repair_id and r.company_id=public.get_my_company_id() and public.user_has_branch_access(r.branch_id)) and public.has_permission('repairs.manage'));
drop policy if exists engineer_part_ledger_select on public.engineer_part_ledger; create policy engineer_part_ledger_branch_select on public.engineer_part_ledger for select to authenticated using(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id));
drop policy if exists inventory_transfers_select on public.inventory_transfers; create policy inventory_transfers_branch_select on public.inventory_transfers for select to authenticated using(company_id=public.get_my_company_id() and (public.user_has_branch_access(from_branch_id) or public.user_has_branch_access(to_branch_id)));
drop policy if exists audit_logs_select on public.audit_logs; create policy audit_logs_branch_select on public.audit_logs for select to authenticated using(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id) and public.has_permission('audit.view'));